// A LATERAL BODY'S NAMES NEVER BIND THE OUTER RELATION — arc JP round 2, on
// FIVE ARMS. Every body here publishes its columns UNALIASED (`SELECT i.id`,
// `SELECT k, v`), so the names it publishes are names the outer relation
// lt_o (id, k, total) — and in the chain cells jp_i x (id, oid, v) — also
// publishes. The seam, enumerated once:
//
//	{outer side bare `o.k`, `o.k - 0`, `o.k + 1`, CAST, coalesce}
//	x {body list: the key's own name `i.k`; a non-key name the outer has
//	   `i.id`; `i.id, i.v`; `i.k, i.v`; a name only the body has `i.v`;
//	   unqualified `k, v`; `i.k, i.id`}
//	x {plain, DISTINCT, ORDER BY … LIMIT 1, LIMIT 1 OFFSET 1, DISTINCT …
//	   LIMIT 1, GROUP BY … count(*)}
//	x {JOIN LATERAL, LEFT JOIN LATERAL} x {named columns, `o.*, s.*`}
//	+ a second outer relation keyed on either relation, bare and `- 0`
//	+ an aliased table whose alias is another table's name (P1: an aliased
//	  table answers to its alias alone)
//	+ the round-1 review's cells (B1, B2, B3, N4).
//
// Four mechanisms answer it (tooling/arcs/jp_join_pairing/jp_landing_notes.md
// §ROUND 2): the lifted key owns a slot (builder.go), a DISTINCT keeps its
// block's name (distinct_rewrite.go), the stage DAG resolves a LATERAL's
// unaliased item to its source (output_rename_resolve.go) and keeps an
// aggregate-published slot as its own name (filter_project_pushdown.go).
//
// Loud, never wrong: a bounded DISTINCT body not over the key alone refuses
// on every arm (arc LT's documented refusal); the 512 KiB arm may refuse a
// build its budget cannot hold (documented). A bare-key LEFT lateral over a
// DISTINCT body, which failed loudly on the stage DAG with ADR-0010's schema
// check, runs single-process since arc JP round 3 (a LEFT join padding a
// grouped arm, dagplan.ErrLateralIdentityDistributed) and answers.

type jpbCell struct{ name, sql string }

func TestArcJPBLateralBodyNamesNeverBindTheOuterRelationOnEveryArm(t *testing.T) {
	if testing.Short() {
		t.Skip("-short: five arms over the arc JP round-2 seam table")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Minute)
	t.Cleanup(cancel)
	arms := jpArms(t, ctx)
	for _, tc := range jpbCells {
		w, ok := jpbPostgres[tc.name]
		if !ok {
			t.Fatalf("%s: no PostgreSQL row set recorded", tc.name)
		}
		t.Run(tc.name, func(t *testing.T) {
			for _, arm := range arms {
				got := arm.run(tc.sql)
				if strings.HasPrefix(w, "ERR ") {
					// PostgreSQL rejects the query: every arm must too.
					if !strings.HasPrefix(got, "ERR ") {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  PostgreSQL rejects it: %s", tc.sql, arm.name, got, w)
					}
					continue
				}
				if class, isLoud := jpbLoud[tc.name+"\x00"+arm.name]; isLoud {
					// A LOUD CELL THAT STARTS ANSWERING FAILS: delete its entry.
					if got == w {
						t.Errorf("%s\n  arm  %s\n  answers PostgreSQL's %s now: delete its jpbLoud entry", tc.sql, arm.name, w)
					} else if !strings.HasPrefix(got, "ERR ") || !strings.Contains(got, class) {
						t.Errorf("%s\n  arm  %s\n  got  %s\n  must refuse with %q (PostgreSQL answers %s)", tc.sql, arm.name, got, class, w)
					}
					continue
				}
				if arm.name == "spilled512k" && strings.HasPrefix(got, "ERR ") &&
					(strings.Contains(got, "memory budget") || strings.Contains(got, "cross join")) {
					continue // the 512 KiB budget's documented loud refusal
				}
				if got != w {
					t.Errorf("%s\n  arm  %s\n  got  %s\n  want %s (PostgreSQL 17.11)", tc.sql, arm.name, got, w)
				}
			}
		})
	}
}

